package com.example.starter.evidence.dto;

import jakarta.validation.constraints.Size;

/**
 * 证物入库请求。保管人取自 X-Actor-Id，初始状态 SEALED、版本 0。
 *
 * @param commandKey   幂等命令键
 * @param evidenceKey  证物业务键，全局唯一
 * @param caseKey      所属案件键
 * @param category     证物类别
 * @param sealNo       封条编号
 * @param locationCode 入库库位编码；为 null 或空表示暂不分配库位（不参与库位迁移）
 */
public record IntakeRequest(
        @jakarta.validation.constraints.NotBlank @Size(max = 64) String commandKey,
        @jakarta.validation.constraints.NotBlank @Size(max = 64) String evidenceKey,
        @jakarta.validation.constraints.NotBlank @Size(max = 64) String caseKey,
        @jakarta.validation.constraints.NotBlank @Size(max = 64) String category,
        @jakarta.validation.constraints.NotBlank @Size(max = 64) String sealNo,
        @Size(max = 64) String locationCode) {

    /**
     * 兼容无库位入库请求的规范化库位（空白视为未分配）。
     */
    public String normalizedLocationCode() {
        return locationCode == null || locationCode.isBlank() ? null : locationCode;
    }
}

