package com.example.starter.evidence;

import java.time.LocalDateTime;

/**
 * 库位实体，对应 storage_location 表。locationCode 全局唯一；enabled=false 表示库位停用。
 *
 * @param id           主键
 * @param locationCode 库位编码，全局唯一
 * @param locationName 库位名称
 * @param enabled      是否启用；false 表示停用，停用库位不得作为迁移目标
 * @param createdAt    建档时间（Asia/Shanghai）
 * @param updatedAt    最近启用/停用变更时间（Asia/Shanghai）
 */
public record StorageLocation(
        Long id,
        String locationCode,
        String locationName,
        boolean enabled,
        LocalDateTime createdAt,
        LocalDateTime updatedAt) {
}

package com.example.starter.evidence;

/**
 * 库位迁移单状态。
 * AWAITING_SECOND 首人已确认、待第二人确认（可撤销）；
 * COMPLETED 第二人已确认完成（终态，不可撤销、不可再确认）；
 * CANCELLED 已撤销（终态，不可再确认）。
 */
public enum MoveStatus {
    AWAITING_SECOND,
    COMPLETED,
    CANCELLED
}

