package com.example.starter.evidence.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotEmpty;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

import java.util.List;

/**
 * 库位迁移确认请求。首人确认与第二人确认使用同一端点：
 * 迁移单不存在时以操作人为第一确认保管人建单；已存在且操作人不同的保管人确认时完成迁移。
 * moveKey 同时作为迁移幂等键：同键成功重放完整迁移结果，失败不占键。
 *
 * @param moveKey         迁移单业务键（迁移幂等键），全局唯一
 * @param evidenceKeys    证物业务键集合；换序视为同参（服务端去重并按字典序规范化）
 * @param sourceLocation  源库位编码
 * @param targetLocation  目标库位编码
 * @param expectedVersion 集合期望版本；确认时每件证物版本均须等于该值
 */
public record MoveConfirmRequest(
        @NotBlank @Size(max = 64) String moveKey,
        @NotEmpty List<@NotBlank @Size(max = 64) String> evidenceKeys,
        @NotBlank @Size(max = 64) String sourceLocation,
        @NotBlank @Size(max = 64) String targetLocation,
        @NotNull Long expectedVersion) {
}

package com.example.starter.evidence.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;

/**
 * 库位建档请求。locationCode 全局唯一，建档后默认启用。
 *
 * @param locationCode 库位编码
 * @param locationName 库位名称
 */
public record LocationUpsertRequest(
        @NotBlank @Size(max = 64) String locationCode,
        @NotBlank @Size(max = 128) String locationName) {
}

package com.example.starter.evidence.dto;

import java.time.LocalDateTime;

/**
 * 库位视图。
 *
 * @param locationCode 库位编码
 * @param locationName 库位名称
 * @param enabled      是否启用
 * @param createdAt    建档时间
