/**
 * 库位迁移单表访问。迁移单只追加：首人确认插入 AWAITING_SECOND 行；
 * 完成与撤销均为条件更新（状态必须仍为 AWAITING_SECOND），终态后历史不可改写。
 */
@Repository
public class LocationMoveOrderRepository {

    private static final MoveOrderRowMapper ROW_MAPPER = new MoveOrderRowMapper();

    private final JdbcTemplate jdbc;

    public LocationMoveOrderRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /**
     * 首人确认建单：状态 AWAITING_SECOND；move_key 冲突由唯一约束拒绝。
     */
    public void insert(String moveKey, String evidenceKeys, String sourceLocation,
                       String targetLocation, long expectedVersion, String firstConfirmer,
                       LocalDateTime now) {
        jdbc.update("""
                        INSERT INTO location_move_order
                            (move_key, evidence_keys, source_location, target_location,
                             expected_version, first_confirmer, second_confirmer, status,
                             created_at, confirmed_at, cancelled_at, cancelled_by)
                        VALUES (?, ?, ?, ?, ?, ?, NULL, ?, ?, NULL, NULL, NULL)
                        """,
                moveKey, evidenceKeys, sourceLocation, targetLocation, expectedVersion,
                firstConfirmer, MoveStatus.AWAITING_SECOND.name(), now);
    }

    /**
     * 按业务键查询迁移单（不加锁）。
     */
    public Optional<LocationMoveOrder> findByKey(String moveKey) {
        List<LocationMoveOrder> rows = jdbc.query(
                "SELECT * FROM location_move_order WHERE move_key = ?", ROW_MAPPER, moveKey);
        return rows.stream().findFirst();
    }

    /**
     * 按业务键查询并锁定迁移单行（SELECT ... FOR UPDATE），用于第二人确认/撤销裁决。
     */
    public Optional<LocationMoveOrder> findByKeyForUpdate(String moveKey) {
        List<LocationMoveOrder> rows = jdbc.query(
                "SELECT * FROM location_move_order WHERE move_key = ? FOR UPDATE",
                ROW_MAPPER, moveKey);
        return rows.stream().findFirst();
    }

    /**
     * 条件完成：仅当迁移单仍为 AWAITING_SECOND 时写入第二确认人与完成时间。
     *
     * @return 是否完成成功（false 表示已被并发完成或撤销）
     */
    public boolean complete(long id, String secondConfirmer, LocalDateTime now) {
        int updated = jdbc.update("""
                        UPDATE location_move_order
                        SET status = ?, second_confirmer = ?, confirmed_at = ?
                        WHERE id = ? AND status = ?
                        """,
                MoveStatus.COMPLETED.name(), secondConfirmer, now,
                id, MoveStatus.AWAITING_SECOND.name());
        return updated == 1;
    }

    /**
     * 条件撤销：仅当迁移单仍为 AWAITING_SECOND 时写入撤销人与撤销时间。
     *
     * @return 是否撤销成功（false 表示已被并发完成或已撤销）
     */
    public boolean cancel(long id, String cancelledBy, LocalDateTime now) {
        int updated = jdbc.update("""
                        UPDATE location_move_order
                        SET status = ?, cancelled_by = ?, cancelled_at = ?
                        WHERE id = ? AND status = ?
                        """,
                MoveStatus.CANCELLED.name(), cancelledBy, now,
                id, MoveStatus.AWAITING_SECOND.name());
        return updated == 1;
    }

    private static final class MoveOrderRowMapper implements RowMapper<LocationMoveOrder> {
        @Override
        public LocationMoveOrder mapRow(ResultSet rs, int rowNum) throws SQLException {
            return new LocationMoveOrder(
                    rs.getLong("id"),
                    rs.getString("move_key"),
                    rs.getString("evidence_keys"),
                    rs.getString("source_location"),
                    rs.getString("target_location"),
                    rs.getLong("expected_version"),
                    rs.getString("first_confirmer"),
                    rs.getString("second_confirmer"),
                    MoveStatus.valueOf(rs.getString("status")),
                    rs.getObject("created_at", LocalDateTime.class),
                    rs.getObject("confirmed_at", LocalDateTime.class),
                    rs.getObject("cancelled_at", LocalDateTime.class),
                    rs.getString("cancelled_by"));
        }
    }
}

