package com.example.starter.evidence;

import com.example.starter.error.ApiException;

import java.util.List;

/**
 * 库位迁移前置条件失败（422）：携带逐项不满足说明。
 * 证物不在库、封条异常、当前库位不等于源库位或版本偏离 expectedVersion 时，
 * 收集集合内全部不满足项一次性返回，而不是遇错即停。
 */
public class MovePreconditionException extends ApiException {

    private final List<ItemViolation> items;

    public MovePreconditionException(List<ItemViolation> items) {
        super(HttpStatus.UNPROCESSABLE_ENTITY, "迁移前置条件不满足，共 " + items.size() + " 项");
        this.items = List.copyOf(items);
    }

    /**
     * @return 不可变的逐项不满足说明
     */
    public List<ItemViolation> items() {
        return items;
    }

    /**
     * 单件证物的不满足说明。
     *
     * @param evidenceKey 证物业务键；缺失证物使用请求中的键
     * @param reason      不满足原因：NOT_FOUND 不存在 / SEAL_ABNORMAL 封条异常 /
     *                    LOCATION_MISMATCH 当前库位不等于源库位 / VERSION_MISMATCH 版本偏离
     */
