 * 以事务提交顺序裁决，终态不可改写。
 *
 * <p>幂等：moveKey 为迁移幂等键，指纹含操作者、规范化证物集合（换序同参）、源/目标库位与版本；
 * 同键成功（COMPLETED）后任意一位确认人重放完整迁移结果；确认失败不写终态、不占键，可换人重试。
 */
@Service
public class LocationMoveService {

    private final LocationMoveOrderRepository moveOrderRepository;
    private final MoveSealSnapshotRepository snapshotRepository;
    private final StorageLocationRepository locationRepository;
    private final EvidenceRepository evidenceRepository;

    public LocationMoveService(LocationMoveOrderRepository moveOrderRepository,
                               MoveSealSnapshotRepository snapshotRepository,
                               StorageLocationRepository locationRepository,
                               EvidenceRepository evidenceRepository) {
        this.moveOrderRepository = moveOrderRepository;
        this.snapshotRepository = snapshotRepository;
        this.locationRepository = locationRepository;
        this.evidenceRepository = evidenceRepository;
    }

    /**
     * 迁移确认：首人建单、不同的第二人完成；完成后同键同参重放完整迁移结果。
     */
    @Transactional
    public MoveResult confirm(String actorId, MoveConfirmRequest request) {
        List<String> keys = normalizeKeys(request.evidenceKeys());
        if (request.sourceLocation().equals(request.targetLocation())) {
            throw ApiException.badRequest("源库位与目标库位不能相同");
        }
        LocationMoveOrder existing = moveOrderRepository.findByKeyForUpdate(request.moveKey())
                .orElse(null);
        if (existing != null) {
            return handleExisting(actorId, request, keys, existing);
        }
        return createAwaiting(actorId, request, keys);
    }

    /**
     * 撤销迁移单：仅首人（第一确认保管人）可在第二人完成前撤销；完成后不可撤销。
     */
    @Transactional
    public MoveOrderView cancel(String actorId, String moveKey) {
        LocationMoveOrder order = moveOrderRepository.findByKeyForUpdate(moveKey)
                .orElseThrow(() -> ApiException.notFound("迁移单不存在: " + moveKey));
        if (!order.firstConfirmer().equals(actorId)) {
            throw ApiException.conflict("仅第一确认保管人可撤销迁移单: " + actorId);
        }
        if (order.status() == MoveStatus.COMPLETED) {
            throw ApiException.conflict("迁移已完成，不可撤销: " + moveKey);
        }
        if (order.status() == MoveStatus.CANCELLED) {
            // 撤销为终态：同键同参重放撤销结果，不重复改写。
            return toView(order);
        }
        LocalDateTime now = LocalDateTime.now();
        if (!moveOrderRepository.cancel(order.id(), actorId, now)) {
            throw ApiException.conflict("迁移单已被并发处理: " + moveKey);
        }
        return toView(moveOrderRepository.findByKey(moveKey).orElseThrow());
    }

    /**
     * 查询迁移单及逐件封签快照。
     */
    @Transactional(readOnly = true)
    public MoveResult getMove(String moveKey) {
        LocationMoveOrder order = moveOrderRepository.findByKey(moveKey)
                .orElseThrow(() -> ApiException.notFound("迁移单不存在: " + moveKey));
        return toResult(order, snapshotRepository.findByMoveKey(moveKey));
    }

    /**
     * 查询证物的逐件封签核验快照历史（只追加、不可变）。
     */
    @Transactional(readOnly = true)
    public List<MoveSealSnapshotView> listSnapshots(String evidenceKey) {
        if (evidenceRepository.findByKey(evidenceKey).isEmpty()) {
            throw ApiException.notFound("证物不存在: " + evidenceKey);
        }
        return snapshotRepository.findByEvidenceKey(evidenceKey).stream()
                .map(this::toView).toList();
    }

    /**
     * 查询库位当前库存证物（按主键升序）。借出未归还证物库位不变但不在库，调用方可按状态区分。
     */
    @Transactional(readOnly = true)
    public List<com.example.starter.evidence.dto.EvidenceView> listInventory(String locationCode) {
        if (locationRepository.findByCode(locationCode).isEmpty()) {
            throw ApiException.notFound("库位不存在: " + locationCode);
        }
        return evidenceRepository.findByLocation(locationCode).stream().map(this::toEvidenceView).toList();
    }

    /**
     * 库位建档：locationCode 唯一，默认启用。
     */
    @Transactional
    public com.example.starter.evidence.dto.StorageLocationView createLocation(
            String actorId, String locationCode, String locationName) {
        if (locationRepository.findByCode(locationCode).isPresent()) {
            throw ApiException.conflict("库位已存在: " + locationCode);
        }
        LocalDateTime now = LocalDateTime.now();
        try {
            locationRepository.insert(locationCode, locationName, now);
        } catch (DuplicateKeyException e) {
            throw ApiException.conflict("库位已存在: " + locationCode);
        }
        return toLocationView(locationRepository.findByCode(locationCode).orElseThrow());
    }

    /**
     * 停用库位：停用后不得作为迁移目标，第二人确认返回 409。
     */
    @Transactional
    public com.example.starter.evidence.dto.StorageLocationView disableLocation(String locationCode) {
        LocationLocation(locationCode);
        locationRepository.setEnabled(locationCode, false, LocalDateTime.now());
        return toLocationView(locationRepository.findByCode(locationCode).orElseThrow());
    }

    /**
     * 重新启用库位。
     */
    @Transactional
    public com.example.starter.evidence.dto.StorageLocationView enableLocation(String locationCode) {
        LocationLocation(locationCode);
        locationRepository.setEnabled(locationCode, true, LocalDateTime.now());
        return toLocationView(locationRepository.findByCode(locationCode).orElseThrow());
    }

    private void LocationLocation(String locationCode) {
        if (locationRepository.findByCode(locationCode).isEmpty()) {
            throw ApiException.notFound("库位不存在: " + locationCode);
        }
    }

    /**
     * 首人确认：校验前置条件后建 AWAITING_SECOND 迁移单，不改动任何证物。
     */
    private MoveResult createAwaiting(String actorId, MoveConfirmRequest request, List<String> keys) {
        requireTargetEnabled(request.targetLocation());
        Map<String, Evidence> evidenceMap = lockAndValidate(keys, request, false);
        LocalDateTime now = LocalDateTime.now();
        try {
            moveOrderRepository.insert(request.moveKey(), String.join(",", keys),
                    request.sourceLocation(), request.targetLocation(), request.expectedVersion(),
                    actorId, now);
        } catch (DuplicateKeyException e) {
            // 并发首人确认：唯一约束裁决后重新锁定迁移单，按已存在单据处理。
            LocationMoveOrder raced = moveOrderRepository.findByKeyForUpdate(request.moveKey())
                    .orElseThrow(() -> ApiException.conflict("迁移键冲突: " + request.moveKey()));
            return handleExisting(actorId, request, keys, raced);
        }
        LocationMoveOrder created = moveOrderRepository.findByKey(request.moveKey()).orElseThrow();
        return toResult(created, List.of());
    }

    /**
     * 已存在迁移单的确认分支：完成则重放；待第二人且操作人不同则执行原子迁移；其余按状态/操作者冲突处理。
     */
    private MoveResult handleExisting(String actorId, MoveConfirmRequest request, List<String> keys,
                                      LocationMoveOrder order) {
        requireSameParams(order, keys, request);
        if (order.status() == MoveStatus.CANCELLED) {
            throw ApiException.conflict("迁移单已撤销，不可再确认: " + request.moveKey());
        }
        if (order.status() == MoveStatus.COMPLETED) {
            // 同键成功重放完整迁移结果：仅两位确认人可重放。
            if (!actorId.equals(order.firstConfirmer())
                    && !actorId.equals(order.secondConfirmer())) {
                throw ApiException.conflict("操作者不是迁移单确认人: " + actorId);
            }
            return toResult(order, snapshotRepository.findByMoveKey(order.moveKey()));
        }
        if (actorId.equals(order.firstConfirmer())) {
            throw ApiException.conflict("须两名不同保管人确认，第二人不能与第一人相同");
        }
        // 第二人确认：单事务内复查全部前置条件，任一不满足整单回滚。
        requireTargetEnabled(order.targetLocation());
        Map<String, Evidence> evidenceMap = lockAndValidate(keys, request, true);
        LocalDateTime now = LocalDateTime.now();
        for (String key : keys) {
            Evidence evidence = evidenceMap.get(key);
            int updated = evidenceRepository.updateLocationIfVersion(
                    key, order.targetLocation(), order.expectedVersion(), now);
            if (updated != 1) {
                // 持锁后仍版本偏离，理论上已被前置校验拦截；保底整单回滚。
                throw ApiException.unprocessable("证物版本已变更，迁移整单回滚: " + key);
            }
            snapshotRepository.insert(order.moveKey(), key, order.sourceLocation(),
                    order.targetLocation(), evidence.sealNo(), EvidenceStatus.SEALED,
                    evidence.version(), order.firstConfirmer(), actorId, now);
        }
        if (!moveOrderRepository.complete(order.id(), actorId, now)) {
            throw ApiException.conflict("迁移单已被并发处理: " + request.moveKey());
        }
        LocationMoveOrder completed = moveOrderRepository.findByKey(order.moveKey()).orElseThrow();
        return toResult(completed, snapshotRepository.findByMoveKey(order.moveKey()));
    }

    /**
     * 目标库位必须存在且启用，否则 409（与借出/待核验同属确认时状态冲突）。
     */
    private void requireTargetEnabled(String targetLocation) {
        StorageLocation target = locationRepository.findByCodeForUpdate(targetLocation)
                .orElseThrow(() -> ApiException.conflict("目标库位不存在: " + targetLocation));
        if (!target.enabled()) {
            throw ApiException.conflict("目标库位已停用，禁止迁入: " + targetLocation);
        }
    }

    /**
     * 锁定集合全部证物行并校验前置条件。
     * 证物借出（BORROWED）或待核验（TRANSFER_PENDING）时整单 409；
     * 其余不满足项（不存在、封条异常、库位不符、版本不符）收集为 422 逐项说明。
     */
    private Map<String, Evidence> lockAndValidate(List<String> keys, MoveConfirmRequest request,
                                                  boolean secondConfirm) {
        List<Evidence> locked = evidenceRepository.findByKeysForUpdate(keys);
        Map<String, Evidence> map = locked.stream()
                .collect(Collectors.toMap(Evidence::evidenceKey, Function.identity()));
        for (String key : keys) {
            Evidence evidence = map.get(key);
            if (evidence != null
                    && (evidence.status() == EvidenceStatus.BORROWED
                    || evidence.status() == EvidenceStatus.TRANSFER_PENDING)) {
                throw ApiException.conflict(
                        "证物" + (evidence.status() == EvidenceStatus.BORROWED ? "借出未归还" : "待核验")
                                + "，禁止确认迁移: " + key);
            }
        }
        List<MovePreconditionException.ItemViolation> violations = new ArrayList<>();
        for (String key : keys) {
            Evidence evidence = map.get(key);
            if (evidence == null) {
                violations.add(MovePreconditionException.ItemViolation.notFound(key));
                continue;
            }
            if (evidence.status() == EvidenceStatus.SEAL_BROKEN) {
                violations.add(MovePreconditionException.ItemViolation.sealAbnormal(key));
            }
            if (!request.sourceLocation().equals(evidence.locationCode())) {
                violations.add(MovePreconditionException.ItemViolation.locationMismatch(
                        key, String.valueOf(evidence.locationCode()), request.sourceLocation()));
            }
            if (evidence.version() != request.expectedVersion()) {
                violations.add(MovePreconditionException.ItemViolation.versionMismatch(
                        key, evidence.version(), request.expectedVersion()));
            }
        }
        if (!violations.isEmpty()) {
            throw new MovePreconditionException(violations);
        }
        return map;
    }

    private void requireSameParams(LocationMoveOrder order, List<String> keys,
                                   MoveConfirmRequest request) {
        List<String> stored = order.evidenceKeyList();
        if (!stored.equals(keys)
                || !order.sourceLocation().equals(request.sourceLocation())
                || !order.targetLocation().equals(request.targetLocation())
                || order.expectedVersion() != request.expectedVersion()) {
            throw ApiException.conflict("迁移键已被不同参数使用: " + request.moveKey());
        }
    }

    /**
     * 证物集合规范化：去重并按字典序升序；集合换序视为同参。
     */
    private List<String> normalizeKeys(List<String> raw) {
        return raw.stream().map(String::trim)
                .collect(Collectors.toCollection(LinkedHashSet::new))
                .stream().sorted(Locale.ROOT).toList();
    }

    private MoveResult toResult(LocationMoveOrder order, List<MoveSealSnapshot> snapshots) {
        return new MoveResult(toView(order), snapshots.stream().map(this::toView).toList());
    }

    private MoveOrderView toView(LocationMoveOrder order) {
        return new MoveOrderView(order.moveKey(), order.evidenceKeyList(),
                order.sourceLocation(), order.targetLocation(), order.expectedVersion(),
                order.firstConfirmer(), order.secondConfirmer(), order.status(),
                order.createdAt(), order.confirmedAt(), order.cancelledAt(), order.cancelledBy());
    }

    private MoveSealSnapshotView toView(MoveSealSnapshot snapshot) {
        return new MoveSealSnapshotView(snapshot.moveKey(), snapshot.evidenceKey(),
                snapshot.sourceLocation(), snapshot.targetLocation(), snapshot.sealNo(),
                snapshot.sealStatus(), snapshot.evidenceVersion(), snapshot.firstConfirmer(),
                snapshot.secondConfirmer(), snapshot.createdAt());
    }

    private com.example.starter.evidence.dto.EvidenceView toEvidenceView(Evidence evidence) {
        return new com.example.starter.evidence.dto.EvidenceView(evidence.evidenceKey(),
                evidence.caseKey(), evidence.category(), evidence.sealNo(), evidence.custodianId(),
                evidence.status(), evidence.locationCode(), evidence.version(),
                evidence.createdAt(), evidence.updatedAt());
    }

    private com.example.starter.evidence.dto.StorageLocationView toLocationView(StorageLocation location) {
        return new com.example.starter.evidence.dto.StorageLocationView(location.locationCode(),
                location.locationName(), location.enabled(), location.createdAt(), location.updatedAt());
    }

    /**
     * 迁移确认结果：迁移单当前视图 + 逐件封签核验快照（完成前为空，完成后含集合内每件证物一条）。
     *
     * @param order     迁移单视图
     * @param snapshots 逐件封签快照
     */
    public record MoveResult(MoveOrderView order, List<MoveSealSnapshotView> snapshots) {
    }
}

