package com.example.starter.evidence;

import com.example.starter.evidence.dto.EvidenceView;
import com.example.starter.evidence.dto.LocationUpsertRequest;
import com.example.starter.evidence.dto.MoveConfirmRequest;
import com.example.starter.evidence.dto.MoveOrderView;
import com.example.starter.evidence.dto.MoveSealSnapshotView;
import com.example.starter.evidence.dto.StorageLocationView;
import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

import java.util.List;

/**
 * 证物库位与双人封签迁移 API。操作人通过 X-Actor-Id 请求头提供。
 * 迁移幂等键为请求体内 moveKey：同键同参成功重放完整迁移结果，失败不占键。
 */
@RestController
@RequestMapping("/api")
@Validated
public class LocationMoveController {

    static final String ACTOR_HEADER = "X-Actor-Id";

    private final LocationMoveService moveService;

    public LocationMoveController(LocationMoveService moveService) {
        this.moveService = moveService;
    }

    /**
     * 库位建档：locationCode 唯一，默认启用。
     */
    @PostMapping("/locations")
    public ResponseEntity<StorageLocationView> createLocation(
            @RequestHeader(ACTOR_HEADER) @NotBlank String actorId,
            @Valid @RequestBody LocationUpsertRequest request) {
        return ResponseEntity.status(HttpStatus.CREATED)
                .body(moveService.createLocation(actorId, request.locationCode(),
                        request.locationName()));
    }

    /**
     * 停用库位：停用后不得作为迁移目标。
     */
    @PostMapping("/locations/{locationCode}/disable")
    public StorageLocationView disableLocation(@PathVariable String locationCode) {
        return moveService.disableLocation(locationCode);
    }

    /**
     * 重新启用库位。
     */
    @PostMapping("/locations/{locationCode}/enable")
    public StorageLocationView enableLocation(@PathVariable String locationCode) {
        return moveService.enableLocation(locationCode);
    }

    /**
     * 查询库位当前库存证物。
     */
    @GetMapping("/locations/{locationCode}/inventory")
    public List<EvidenceView> inventory(@PathVariable String locationCode) {
        return moveService.listInventory(locationCode);
    }

    /**
     * 迁移确认：首人建单待第二人，不同的第二人完成；完成后同键同参重放完整结果。
     */
    @PostMapping("/location-moves/confirm")
    public LocationMoveService.MoveResult confirm(
            @RequestHeader(ACTOR_HEADER) @NotBlank String actorId,
            @Valid @RequestBody MoveConfirmRequest request) {
        return moveService.confirm(actorId, request);
    }

    /**
     * 撤销迁移单：仅第一确认保管人可在完成前撤销，完成后不可撤销。
     */
    @PostMapping("/location-moves/{moveKey}/cancel")
    public MoveOrderView cancel(@RequestHeader(ACTOR_HEADER) @NotBlank String actorId,
                                @PathVariable String moveKey) {
        return moveService.cancel(actorId, moveKey);
    }

    /**
     * 查询迁移单及逐件封签快照。
     */
    @GetMapping("/location-moves/{moveKey}")
    public LocationMoveService.MoveResult getMove(@PathVariable String moveKey) {
        return moveService.getMove(moveKey);
    }

    /**
     * 查询单件证物的历史迁移封签核验快照。
     */
    @GetMapping("/evidence/{evidenceKey}/move-seal-snapshots")
    public List<MoveSealSnapshotView> snapshots(@PathVariable String evidenceKey) {
        return moveService.listSnapshots(evidenceKey);
    }
}

