public com.example.starter.evidence.dto.StorageLocationView enableLocation(String locationCode) {
    requireLocation(locationCode);
    locationRepository.setEnabled(locationCode, true, LocalDateTime.now());
    return toLocationView(locationRepository.findByCode(locationCode).orElseThrow());
}

private void requireLocation(String locationCode) {
    if (locationRepository.findByCode(locationCode).isEmpty()) {
        throw ApiException.notFound("库位不存在: " + locationCode);
    }
}

/**
 * 首人确认：校验前置条件后建 AWAITING_SECOND 迁移单，不改动任何证物。
 */
private MoveResult createAwaiting(String actorId, MoveConfirmRequest request, List<String> keys) {
    requireTargetEnabled(request.targetLocation());
    Map<String, Evidence> evidenceMap = lockAndValidate(keys, request, false);
    LocalDateTime now = LocalDateTime.now();
    try {
        moveOrderRepository.insert(request.moveKey(), String.join(",", keys),
                request.sourceLocation(), request.targetLocation(), request.expectedVersion(),
                actorId, now);
    } catch (DuplicateKeyException e) {
        // 并发首人确认：唯一约束裁决后重新锁定迁移单，按已存在单据处理。
        LocationMoveOrder raced = moveOrderRepository.findByKeyForUpdate(request.moveKey())
                .orElseThrow(() -> ApiException.conflict("迁移键冲突: " + request.moveKey()));
        return handleExisting(actorId, request, keys, raced);
    }
    LocationMoveOrder created = moveOrderRepository.findByKey(request.moveKey()).orElseThrow();
    return toResult(created, List.of());
}

/**
 * 已存在迁移单的确认分支：完成则重放；待第二人且操作人不同则执行原子迁移；其余按状态/操作者冲突处理。
 */
private MoveResult handleExisting(String actorId, MoveConfirmRequest request, List<String> keys,
                                  LocationMoveOrder order) {
    requireSameParams(order, keys, request);
    if (order.status() == MoveStatus.CANCELLED) {
        throw ApiException.conflict("迁移单已撤销，不可再确认: " + request.moveKey());
    }
    if (order.status() == MoveStatus.COMPLETED) {
        // 同键成功重放完整迁移结果：仅两位确认人可重放。
        if (!actorId.equals(order.firstConfirmer())
                && !actorId.equals(order.secondConfirmer())) {
            throw ApiException.conflict("操作者不是迁移单确认人: " + actorId);
        }
        return toResult(order, snapshotRepository.findByMoveKey(order.moveKey()));
    }
    if (order.status() == MoveStatus.AWAITING_SECOND
            && actorId.equals(order.firstConfirmer())) {
        // 首人确认的幂等重放：迁移尚未完成，原样返回待第二人状态，不重复建单。
        return toResult(order, List.of());
    }
    if (order.status() == MoveStatus.AWAITING_SECOND) {
        return completeBySecond(actorId, request, keys, order);
    }
    throw ApiException.conflict("迁移单状态不允许确认: " + request.moveKey());
}

