/**
 * 计算请求指纹：操作类型 + 操作人 + 证物键 + 请求体规范化 JSON 的 SHA-256。
 */
public String hash(String operation, String actorId, String evidenceKey, Object request) {
    try {
        String canonical = String.join("\n",
                operation,
                actorId == null ? "" : actorId,
                evidenceKey == null ? "" : evidenceKey,
                objectMapper.writeValueAsString(request));
        return sha256(canonical);
    } catch (Exception e) {
        throw new IllegalStateException("请求序列化失败", e);
    }
}

/**
 * 计算库位迁移 moveKey 指纹：操作类型 + 操作者 + 规范化证物集合（去重、字典序，调用方先行规范化）
 * + 源/目标库位 + 期望版本逐段拼接的 SHA-256。集合换序因规范化而得到相同指纹。
 */
public String moveFingerprint(String operation, String actorId, String canonicalEvidenceKeys,
                              String sourceLocation, String targetLocation, long expectedVersion) {
    String canonical = String.join("\n",
            operation,
            actorId == null ? "" : actorId,
            canonicalEvidenceKeys == null ? "" : canonicalEvidenceKeys,
            sourceLocation == null ? "" : sourceLocation,
            targetLocation == null ? "" : targetLocation,
            Long.toString(expectedVersion));
    return sha256(canonical);
}

private static String sha256(String canonical) {
    try {
        MessageDigest digest = MessageDigest.getInstance("SHA-256");
        return HexFormat.of().formatHex(digest.digest(canonical.getBytes(StandardCharsets.UTF_8)));
    } catch (NoSuchAlgorithmException e) {
        throw new IllegalStateException("SHA-256 不可用", e);
    }
}

