package com.example.starter.evidence;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.MvcResult;

import java.time.LocalDateTime;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;

import static org.assertj.core.api.Assertions.assertThat;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;

/**
 * 证物库位迁移与双人封签核验 API 测试：双人确认、集合原子迁移、逐件封签快照、
 * 撤销语义、422 逐项说明、409 状态冲突与 moveKey 幂等重放，全部基于真实 H2（MySQL 兼容模式）。
 */
@SpringBootTest
@AutoConfigureMockMvc
class LocationMoveApiTest {

    private static final String ACTOR_HEADER = "X-Actor-Id";
    private static final String SRC = "SRC-" + UUID.randomUUID().toString().substring(0, 8);
    private static final String TGT = "TGT-" + UUID.randomUUID().toString().substring(0, 8);

    @Autowired
    private MockMvc mockMvc;

    @Autowired
    private ObjectMapper objectMapper;

    private String uniqueKey(String prefix) {
        return prefix + "-" + UUID.randomUUID().toString().substring(0, 12);
    }

    private void createLocation(String code) throws Exception {
        Map<String, Object> body = new LinkedHashMap<>();
        body.put("locationCode", code);
        body.put("locationName", "库位 " + code);
        MvcResult result = mockMvc.perform(post("/api/locations")
                        .header(ACTOR_HEADER, "admin")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(objectMapper.writeValueAsString(body)))
                .andReturn();
        assertThat(result.getResponse().getStatus()).isEqualTo(201);
    }

    private String intakeAt(String actor, String location) throws Exception {
        String evidenceKey = uniqueKey("EV");
        Map<String, Object> body = new LinkedHashMap<>();
        body.put("commandKey", uniqueKey("CMD"));
        body.put("evidenceKey", evidenceKey);
        body.put("caseKey", "CASE-1");
        body.put("category", "DOCUMENT");
        body.put("sealNo", "SEAL-" + evidenceKey);
        body.put("locationCode", location);
        MvcResult result = mockMvc.perform(post("/api/evidence")
                        .header(ACTOR_HEADER, actor)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(objectMapper.writeValueAsString(body)))
                .andReturn();
        assertThat(result.getResponse().getStatus()).isEqualTo(201);
        return evidenceKey;
    }

    private Map<String, Object> moveBody(String moveKey, List<String> evidenceKeys,
                                         String source, String target, long expectedVersion) {
        Map<String, Object> body = new LinkedHashMap<>();
        body.put("moveKey", moveKey);
        body.put("evidenceKeys", evidenceKeys);
        body.put("sourceLocation", source);
        body.put("targetLocation", target);
        body.put("expectedVersion", expectedVersion);
        return body;
    }

    private MvcResult confirm(String actor, String moveKey, List<String> keys,
                              String source, String target, long expectedVersion) throws Exception {
        return mockMvc.perform(post("/api/location-moves/confirm")
                        .header(ACTOR_HEADER, actor)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(objectMapper.writeValueAsString(
                                moveBody(moveKey, keys, source, target, expectedVersion))))
                .andReturn();
    }

    private MvcResult cancel(String actor, String moveKey) throws Exception {
        return mockMvc.perform(post("/api/location-moves/{key}/cancel", moveKey)
                        .header(ACTOR_HEADER, actor))
                .andReturn();
    }

    private JsonNode getMove(String moveKey) throws Exception {
        MvcResult result = mockMvc.perform(get("/api/location-moves/{key}", moveKey))
                .andReturn();
        assertThat(result.getResponse().getStatus()).isEqualTo(200);
        return objectMapper.readTree(result.getResponse().getContentAsString());
    }

    private JsonNode inventory(String location) throws Exception {
        MvcResult result = mockMvc.perform(get("/api/locations/{code}/inventory", location))
                .andReturn();
        assertThat(result.getResponse().getStatus()).isEqualTo(200);
        return objectMapper.readTree(result.getResponse().getContentAsString());
    }

    @Test
    void twoDifferentCustodiansCompleteAtomicSetMoveWithSnapshots() throws Exception {
        createLocation(SRC);
        createLocation(TGT);
        String ev1 = intakeAt("alice", SRC);
        String ev2 = intakeAt("alice", SRC);
        String moveKey = uniqueKey("MOVE");
        List<String> keys = List.of(ev1, ev2);

        MvcResult first = confirm("alice", moveKey, keys, SRC, TGT, 0);
        assertThat(first.getResponse().getStatus()).isEqualTo(200);
        JsonNode firstBody = objectMapper.readTree(first.getResponse().getContentAsString());
        assertThat(firstBody.get("order").get("status").asText()).isEqualTo("AWAITING_SECOND");
        assertThat(firstBody.get("order").get("firstConfirmer").asText()).isEqualTo("alice");
        assertThat(firstBody.get("order").get("secondConfirmer").isNull()).isTrue();
        assertThat(firstBody.get("snapshots")).isEmpty();
        // 首人确认不改证物库位与版本
        assertThat(inventory(TGT)).isEmpty();

        MvcResult second = confirm("bob", moveKey, keys, SRC, TGT, 0);
        assertThat(second.getResponse().getStatus()).isEqualTo(200);
        JsonNode completed = objectMapper.readTree(second.getResponse().getContentAsString());
        assertThat(completed.get("order").get("status").asText()).isEqualTo("COMPLETED");
        assertThat(completed.get("order").get("secondConfirmer").asText()).isEqualTo("bob");
        assertThat(completed.get("snapshots")).hasSize(2);

        // 整组库位原子切换、版本自增；源库位清空，目标库位有两件
        JsonNode targetInventory = inventory(TGT);
        assertThat(targetInventory).hasSize(2);
        assertThat(targetInventory.findValuesAsText("evidenceKey")).containsExactlyInAnyOrder(ev1, ev2);
        assertThat(targetInventory.findValuesAsText("locationCode")).containsOnly(TGT);
        assertThat(inventory(SRC)).isEmpty();

        // 逐件封签快照内容正确且为完成前版本 0
        for (JsonNode snapshot : completed.get("snapshots")) {
            assertThat(snapshot.get("sourceLocation").asText()).isEqualTo(SRC);
            assertThat(snapshot.get("targetLocation").asText()).isEqualTo(TGT);
            assertThat(snapshot.get("sealStatus").asText()).isEqualTo("SEALED");
            assertThat(snapshot.get("evidenceVersion").asLong()).isEqualTo(0L);
            assertThat(snapshot.get("firstConfirmer").asText()).isEqualTo("alice");
            assertThat(snapshot.get("secondConfirmer").asText()).isEqualTo("bob");
        }
        assertThat(completed.get("snapshots").findValuesAsText("evidenceKey"))
                .containsExactlyInAnyOrder(ev1, ev2);
    }

    @Test
    void reorderedSetIsTreatedAsSameParameters() throws Exception {
        createLocation(SRC);
        createLocation(TGT);
        String ev1 = intakeAt("alice", SRC);
        String ev2 = intakeAt("alice", SRC);
        String moveKey = uniqueKey("MOVE");

        MvcResult first = confirm("alice", moveKey, List.of(ev2, ev1), SRC, TGT, 0);
        assertThat(first.getResponse().getStatus()).isEqualTo(200);
        MvcResult second = confirm("bob", moveKey, List.of(ev1, ev2), SRC, TGT, 0);
        assertThat(second.getResponse().getStatus()).isEqualTo(200);

        JsonNode order = getMove(moveKey).get("order");
        assertThat(order.get("evidenceKeys")).containsExactly(
                objectMapper.getNodeFactory().textNode(ev1),
                objectMapper.getNodeFactory().textNode(ev2));
    }

    @Test
    void sameCustodianCannotBeSecondConfirmer() throws Exception {
        createLocation(SRC);
        createLocation(TGT);
        String ev1 = intakeAt("alice", SRC);
        String moveKey = uniqueKey("MOVE");

        assertThat(confirm("alice", moveKey, List.of(ev1), SRC, TGT, 0).getStatus())
                .isEqualTo(200);
        // 第一人重复确认只重放待第二人结果，不会自行完成
        MvcResult replay = confirm("alice", moveKey, List.of(ev1), SRC, TGT, 0);
        assertThat(replay.getResponse().getStatus()).isEqualTo(200);
        assertThat(objectMapper.readTree(replay.getResponse().getContentAsString())
                .get("order").get("status").asText()).isEqualTo("AWAITING_SECOND");
        assertThat(getMove(moveKey).get("order").get("status").asText())
                .isEqualTo("AWAITING_SECOND");

        // 不同的第二人完成
        assertThat(confirm("bob", moveKey, List.of(ev1), SRC, TGT, 0).getStatus())
                .isEqualTo(200);
        assertThat(getMove(moveKey).get("order").get("status").asText()).isEqualTo("COMPLETED");
    }

    @Test
    void cancelAfterFirstConfirmBlocksFurtherConfirmation() throws Exception {
        createLocation(SRC);
        createLocation(TGT);
        String ev1 = intakeAt("alice", SRC);
        String moveKey = uniqueKey("MOVE");

        assertThat(confirm("alice", moveKey, List.of(ev1), SRC, TGT, 0).getStatus())
                .isEqualTo(200);
        MvcResult cancelled = cancel("alice", moveKey);
        assertThat(cancelled.getResponse().getStatus()).isEqualTo(200);
        assertThat(objectMapper.readTree(cancelled.getResponse().getContentAsString())
                .get("status").asText()).isEqualTo("CANCELLED");

        // 撤销后不可再确认：第二人、第一人都返回 409
        assertThat(confirm("bob", moveKey, List.of(ev1), SRC, TGT, 0).getStatus())
                .isEqualTo(409);
        assertThat(confirm("alice", moveKey, List.of(ev1), SRC, TGT, 0).getStatus())
                .isEqualTo(409);
        // 证物仍在源库位、无快照
        assertThat(inventory(SRC)).hasSize(1);
        assertThat(getMove(moveKey).get("snapshots")).isEmpty();
    }

    @Test
    void nonFirstCustodianCannotCancelAndCompletedMoveCannotBeCancelled() throws Exception {
        createLocation(SRC);
        createLocation(TGT);
        String ev1 = intakeAt("alice", SRC);
        String moveKey = uniqueKey("MOVE");
        confirm("alice", moveKey, List.of(ev1), SRC, TGT, 0);

        assertThat(cancel("bob", moveKey).getStatus()).isEqualTo(409);
        assertThat(confirm("bob", moveKey, List.of(ev1), SRC, TGT, 0).getStatus())
                .isEqualTo(200);
        // 完成后第一人也不可撤销
        assertThat(cancel("alice", moveKey).getStatus()).isEqualTo(409);
        assertThat(getMove(moveKey).get("order").get("status").asText()).isEqualTo("COMPLETED");
    }

    @Test
    void preconditionFailuresReturn422WithPerItemReasons() throws Exception {
        createLocation(SRC);
        createLocation(TGT);
        String atSource = intakeAt("alice", SRC);
        String elsewhere = intakeAt("alice", TGT);
        String broken = intakeAt("alice", SRC);

        // 将 broken 封条核验为异常
        Map<String, Object> inspect = new LinkedHashMap<>();
        inspect.put("commandKey", uniqueKey("CMD"));
        inspect.put("passed", false);
        inspect.put("note", "cracked");
        mockMvc.perform(post("/api/evidence/{key}/seal-inspections", broken)
                        .header(ACTOR_HEADER, "alice")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(objectMapper.writeValueAsString(inspect)))
                .andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isOk());

        String moveKey = uniqueKey("MOVE");
        MvcResult result = confirm("alice", moveKey,
                List.of(atSource, elsewhere, broken, uniqueKey("EV-MISSING")), SRC, TGT, 0);
        assertThat(result.getResponse().getStatus()).isEqualTo(422);
        JsonNode error = objectMapper.readTree(result.getResponse().getContentAsString());
        assertThat(error.get("status").asInt()).isEqualTo(422);
        Map<String, String> reasons = new LinkedHashMap<>();
        for (JsonNode item : error.get("items")) {
            reasons.put(item.get("evidenceKey").asText(), item.get("reason").asText());
        }
        assertThat(reasons).containsKeys(elsewhere, broken);
        assertThat(reasons.get(elsewhere)).startsWith("LOCATION_MISMATCH");
        assertThat(reasons.get(broken)).startsWith("SEAL_ABNORMAL");
        assertThat(reasons.keySet()).anyMatch(k -> k.startsWith("EV-MISSING"));
        assertThat(reasons.get(atSource)).isNull();
        // 失败不占键、不建单
        assertThat(mockMvc.perform(get("/api/location-moves/{key}", moveKey))
                .andReturn().getResponse().getStatus()).isEqualTo(404);
    }

    @Test
    void versionMismatchAtSecondConfirmationRollsBackWholeMove() throws Exception {
        createLocation(SRC);
        createLocation(TGT);
        String ev1 = intakeAt("alice", SRC);
        String ev2 = intakeAt("alice", SRC);
        String moveKey = uniqueKey("MOVE");
        List<String> keys = List.of(ev1, ev2);

        confirm("alice", moveKey, keys, SRC, TGT, 0);

        // 首人确认后通过一次交接发起+取消使证物版本偏离（仍为 SEALED、仍在 SRC）
        initiateAndCancel(ev1, "carol");

        MvcResult second = confirm("bob", moveKey, keys, SRC, TGT, 0);
        assertThat(second.getResponse().getStatus()).isEqualTo(422);
        JsonNode error = objectMapper.readTree(second.getResponse().getContentAsString());
        assertThat(error.get("items").findValuesAsText("evidenceKey")).contains(ev1);

        // 整单回滚：无库位变更、无快照，迁移单仍待第二人，可被撤销
        assertThat(inventory(SRC)).hasSize(2);
        assertThat(getMove(moveKey).get("snapshots")).isEmpty();
        assertThat(getMove(moveKey).get("order").get("status").asText())
                .isEqualTo("AWAITING_SECOND");
        assertThat(cancel("alice", moveKey).getStatus()).isEqualTo(200);
    }

    private void initiateAndCancel(String evidenceKey, String receiver) throws Exception {
        Map<String, Object> body = new LinkedHashMap<>();
        body.put("commandKey", uniqueKey("CMD"));
        body.put("toCustodian", receiver);
        mockMvc.perform(post("/api/evidence/{key}/transfers", evidenceKey)
                        .header(ACTOR_HEADER, "alice")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(objectMapper.writeValueAsString(body)))
                .andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isOk());
        Map<String, Object> cancelBody = new LinkedHashMap<>();
        cancelBody.put("commandKey", uniqueKey("CMD"));
        mockMvc.perform(post("/api/evidence/{key}/transfers/cancel", evidenceKey)
                        .header(ACTOR_HEADER, "alice")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(objectMapper.writeValueAsString(cancelBody)))
                .andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isOk());
    }

    @Test
    void disabledTargetLocationReturns409() throws Exception {
        createLocation(SRC);
        createLocation(TGT);
        String ev1 = intakeAt("alice", SRC);
        mockMvc.perform(post("/api/locations/{code}/disable", TGT))
                .andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isOk());

        MvcResult result = confirm("alice", uniqueKey("MOVE"), List.of(ev1), SRC, TGT, 0);
        assertThat(result.getResponse().getStatus()).isEqualTo(409);
    }

    @Test
    void borrowedOrPendingEvidenceReturns409() throws Exception {
        createLocation(SRC);
        createLocation(TGT);
        String borrowed = intakeAt("alice", SRC);
        String pending = intakeAt("alice", SRC);

        // 借出未归还
        Map<String, Object> loan = new LinkedHashMap<>();
        loan.put("commandKey", uniqueKey("CMD"));
        loan.put("loanKey", uniqueKey("LOAN"));
        loan.put("borrowerId", "zoe");
        loan.put("purpose", "鉴定");
        loan.put("dueAt", LocalDateTime.now().plusHours(2).toString());
        mockMvc.perform(post("/api/evidence/{key}/loans", borrowed)
                        .header(ACTOR_HEADER, "alice")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(objectMapper.writeValueAsString(loan)))
                .andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isOk());
        assertThat(confirm("alice", uniqueKey("MOVE"), List.of(borrowed), SRC, TGT, 0).getStatus())
                .isEqualTo(409);

        // 待核验（TRANSFER_PENDING）
        Map<String, Object> transfer = new LinkedHashMap<>();
        transfer.put("commandKey", uniqueKey("CMD"));
        transfer.put("toCustodian", "carol");
        mockMvc.perform(post("/api/evidence/{key}/transfers", pending)
                        .header(ACTOR_HEADER, "alice")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(objectMapper.writeValueAsString(transfer)))
                .andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isOk());
        assertThat(confirm("alice", uniqueKey("MOVE"), List.of(pending), SRC, TGT, 0).getStatus())
                .isEqualTo(409);
    }

    @Test
    void completedMoveReplaysFullResultToConfirmersButNotOthers() throws Exception {
        createLocation(SRC);
        createLocation(TGT);
        String ev1 = intakeAt("alice", SRC);
        String moveKey = uniqueKey("MOVE");
        confirm("alice", moveKey, List.of(ev1), SRC, TGT, 0);
        MvcResult completed = confirm("bob", moveKey, List.of(ev1), SRC, TGT, 0);
        assertThat(completed.getResponse().getStatus()).isEqualTo(200);

        MvcResult replayAlice = confirm("alice", moveKey, List.of(ev1), SRC, TGT, 0);
        MvcResult replayBob = confirm("bob", moveKey, List.of(ev1), SRC, TGT, 0);
        assertThat(replayAlice.getResponse().getStatus()).isEqualTo(200);
        assertThat(replayBob.getResponse().getStatus()).isEqualTo(200);
        assertThat(replayAlice.getResponse().getContentAsString())
                .isEqualTo(completed.getResponse().getContentAsString());
        assertThat(replayBob.getResponse().getContentAsString())
                .isEqualTo(completed.getResponse().getContentAsString());
        // 第三人不能重放
        assertThat(confirm("carol", moveKey, List.of(ev1), SRC, TGT, 0).getStatus())
                .isEqualTo(409);
        // 重放不产生重复快照
        assertThat(getMove(moveKey).get("snapshots")).hasSize(1);
    }

    @Test
    void failedConfirmationDoesNotOccupyMoveKey() throws Exception {
        createLocation(SRC);
        createLocation(TGT);
        String ev1 = intakeAt("alice", SRC);
        String moveKey = uniqueKey("MOVE");

        // 错误版本：422，不占键
        assertThat(confirm("alice", moveKey, List.of(ev1), SRC, TGT, 99).getStatus())
                .isEqualTo(422);
        // 同键以正确参数首人确认成功
        assertThat(confirm("alice", moveKey, List.of(ev1), SRC, TGT, 0).getStatus())
                .isEqualTo(200);
        assertThat(confirm("bob", moveKey, List.of(ev1), SRC, TGT, 0).getStatus())
                .isEqualTo(200);
        assertThat(getMove(moveKey).get("order").get("status").asText()).isEqualTo("COMPLETED");
    }

    @Test
    void sameMoveKeyWithDifferentParamsReturns409() throws Exception {
        createLocation(SRC);
        createLocation(TGT);
        String ev1 = intakeAt("alice", SRC);
        String other = uniqueKey("EV");
        String ev2 = intakeAt("alice", SRC);
        String moveKey = uniqueKey("MOVE");

        assertThat(confirm("alice", moveKey, List.of(ev1), SRC, TGT, 0).getStatus())
                .isEqualTo(200);
        // 同键改集合
        assertThat(confirm("alice", moveKey, List.of(ev1, ev2), SRC, TGT, 0).getStatus())
                .isEqualTo(409);
        // 同键改目标库位
        assertThat(confirm("alice", moveKey, List.of(ev1), SRC, "OTHER-" + other, 0).getStatus())
                .isEqualTo(409);
    }

    @Test
    void perEvidenceSnapshotHistoryIsQueryableAndImmutable() throws Exception {
        createLocation(SRC);
        createLocation(TGT);
        String ev1 = intakeAt("alice", SRC);
        String moveKey = uniqueKey("MOVE");
        confirm("alice", moveKey, List.of(ev1), SRC, TGT, 0);
        confirm("bob", moveKey, List.of(ev1), SRC, TGT, 0);

        MvcResult result = mockMvc.perform(
                        get("/api/evidence/{key}/move-seal-snapshots", ev1)).andReturn();
        assertThat(result.getResponse().getStatus()).isEqualTo(200);
        JsonNode snapshots = objectMapper.readTree(result.getResponse().getContentAsString());
        assertThat(snapshots).hasSize(1);
        assertThat(snapshots.get(0).get("moveKey").asText()).isEqualTo(moveKey);
    }
}

