    private String intake(String custodian, String location) {
        String key = uniqueKey("EV");
        evidenceController.intake(custodian, new IntakeRequest(uniqueKey("CMD"), key,
                "CASE-1", "DOCUMENT", "SEAL-" + key.substring(key.length() - 6), location));
        return key;
    }

    private MoveConfirmRequest moveRequest(String moveKey, List<String> keys, long version) {
        return new MoveConfirmRequest(moveKey, keys, src, tgt, version);
    }

    private Integer confirm(String actor, MoveConfirmRequest request) {
        try {
            moveController.confirm(actor, request);
            return 200;
        } catch (ApiException e) {
            return e.status().value();
        }
    }

    /**
     * 并发协调：所有线程就绪后同时放行，返回各调用的 HTTP 状态码。
     */
    private List<Integer> runConcurrently(Callable<Integer> first, Callable<Integer> second)
            throws Exception {
        ExecutorService executor = Executors.newFixedThreadPool(2);
        try {
            CountDownLatch ready = new CountDownLatch(2);
            CountDownLatch start = new CountDownLatch(1);
            Callable<Integer> wrapped = () -> {
                ready.countDown();
                start.await(5, TimeUnit.SECONDS);
                return first.call();
            };
            Future<Integer> f1 = executor.submit(wrapped);
            Future<Integer> f2 = executor.submit(() -> {
                ready.countDown();
                start.await(5, TimeUnit.SECONDS);
                return second.call();
            });
            assertThat(ready.await(5, TimeUnit.SECONDS)).isTrue();
            start.countDown();
            return List.of(f1.get(20, TimeUnit.SECONDS), f2.get(20, TimeUnit.SECONDS));
        } finally {
            executor.shutdownNow();
        }
    }

    @Test
    void concurrentSecondConfirmationsCompleteExactlyOnce() throws Exception {
        String ev1 = intake("alice", src);
        String ev2 = intake("alice", src);
        String moveKey = uniqueKey("MOVE");
        moveController.confirm("alice", moveRequest(moveKey, List.of(ev1, ev2), 0));

        MoveConfirmRequest request = moveRequest(moveKey, List.of(ev1, ev2), 0);
        List<Integer> statuses = runConcurrently(
                () -> confirm("bob", request),
                () -> confirm("carol", request));

        // 仅一名第二确认人成功，另一人在终态后得到 409
        assertThat(statuses).containsExactlyInAnyOrder(200, 409);

        LocationMoveService.MoveResult result = moveService.getMove(moveKey);
        assertThat(result.order().status()).isEqualTo(MoveStatus.COMPLETED);
        assertThat(result.order().firstConfirmer()).isEqualTo("alice");
        assertThat(List.of("bob", "carol")).contains(result.order().secondConfirmer());
        // 快照恰好每件一条，不因并发重复写入
        assertThat(result.snapshots()).hasSize(2);
        // 全部证物仅迁移一次：目标库位两件、版本均为 1
        List<String> targetKeys = moveService.listInventory(tgt).stream()
                .map(ev -> ev.evidenceKey()).toList();
        assertThat(targetKeys).containsExactlyInAnyOrder(ev1, ev2);
        assertThat(moveService.listInventory(src)).isEmpty();
        assertThat(moveService.listInventory(tgt)).allMatch(ev -> ev.version() == 1);
    }

    @Test
    void concurrentSecondConfirmationAndCancelAdjudicateByCommitOrder() throws Exception {
        String ev1 = intake("alice", src);
        String moveKey = uniqueKey("MOVE");
        moveController.confirm("alice", moveRequest(moveKey, List.of(ev1), 0));

        MoveConfirmRequest request = moveRequest(moveKey, List.of(ev1), 0);
        List<Integer> statuses = runConcurrently(
                () -> confirm("bob", request),
                () -> {
                    try {
                        moveController.cancel("alice", moveKey);
                        return 200;
                    } catch (ApiException e) {
                        return e.status().value();
                    }
                });

        // 完成与撤销互斥：恰好一个 200，另一个 409
        assertThat(statuses).containsExactlyInAnyOrder(200, 409);
        LocationMoveService.MoveResult result = moveService.getMove(moveKey);
        Evidence evidence = moveService.listInventory(result.order().status() == MoveStatus.COMPLETED
                ? tgt : src).stream().filter(ev -> ev.evidenceKey().equals(ev1)).findFirst()
                .orElseThrow();
        if (result.order().status() == MoveStatus.COMPLETED) {
            // 第二人先提交：库位切换、有快照
            assertThat(result.snapshots()).hasSize(1);
            assertThat(evidence.locationCode()).isEqualTo(tgt);
        } else {
            // 撤销先提交：库位不变、无快照，且不可再确认
            assertThat(result.order().status()).isEqualTo(MoveStatus.CANCELLED);
            assertThat(result.snapshots()).isEmpty();
            assertThat(evidence.locationCode()).isEqualTo(src);
            assertThat(confirm("bob", request)).isEqualTo(409);
        }
    }

    @Test
    void concurrentMoveCompletionAndBorrowNeverLeaveInconsistentState() throws Exception {
        String ev1 = intake("alice", src);
        String moveKey = uniqueKey("MOVE");
        moveController.confirm("alice", moveRequest(moveKey, List.of(ev1), 0));

        MoveConfirmRequest request = moveRequest(moveKey, List.of(ev1), 0);
        Callable<Integer> borrow = () -> {
            try {
                evidenceController.borrow("alice", ev1, new LoanCreateRequest(uniqueKey("CMD"),
                        uniqueKey("LOAN"), "zoe", "鉴定", LocalDateTime.now().plusHours(2)));
                return 200;
            } catch (ApiException e) {
                return e.status().value();
            }
        };
        List<Integer> statuses = runConcurrently(() -> confirm("bob", request), borrow);

        LocationMoveService.MoveResult result = moveService.getMove(moveKey);
        String finalLocation = result.order().status() == MoveStatus.COMPLETED ? tgt : src;
        Evidence evidence = moveService.listInventory(finalLocation).stream()
                .filter(ev -> ev.evidenceKey().equals(ev1)).findFirst().orElseThrow();

        if (result.order().status() == MoveStatus.COMPLETED) {
            // 迁移先提交：借出随后仍可成功（证物 SEALED、保管人未变）
            assertThat(statuses).contains(200);
            assertThat(evidence.status()).isEqualTo(EvidenceStatus.BORROWED);
            assertThat(evidence.locationCode()).isEqualTo(tgt);
        } else {
            // 借出先提交：证物借出，第二人确认必须 409，迁移仍待第二人
            assertThat(statuses.get(0)).isEqualTo(409);
            assertThat(statuses.get(1)).isEqualTo(200);
            assertThat(evidence.status()).isEqualTo(EvidenceStatus.BORROWED);
            assertThat(evidence.locationCode()).isEqualTo(src);
            assertThat(result.order().status()).isEqualTo(MoveStatus.AWAITING_SECOND);
        }
    }

    @Test
    void concurrentFirstConfirmationsByDifferentCustodiansStillSatisfyTwoPersonRule() throws Exception {
        String ev1 = intake("alice", src);
        String moveKey = uniqueKey("MOVE");
        MoveConfirmRequest request = moveRequest(moveKey, List.of(ev1), 0);

        // 两名不同保管人同时首人确认：唯一约束裁决出建单方，另一方在事务回滚后重入成为第二人
        List<Integer> statuses = runConcurrently(
                () -> confirm("alice", request),
                () -> confirm("bob", request));

        assertThat(statuses).containsOnly(200);
        LocationMoveService.MoveResult result = moveService.getMove(moveKey);
        assertThat(result.order().status()).isEqualTo(MoveStatus.COMPLETED);
        assertThat(result.order().firstConfirmer()).isNotEqualTo(result.order().secondConfirmer());
        assertThat(result.snapshots()).hasSize(1);
        assertThat(moveService.listInventory(tgt)).hasSize(1);
    }

    @Test
    void concurrentFirstConfirmationsBySameCustodianNeverCompleteOrDuplicate() throws Exception {
        String ev1 = intake("alice", src);
        String moveKey = uniqueKey("MOVE");
        MoveConfirmRequest request = moveRequest(moveKey, List.of(ev1), 0);

        List<Integer> statuses = runConcurrently(
                () -> confirm("alice", request),
                () -> confirm("alice", request));

        assertThat(statuses).containsOnly(200);
        LocationMoveService.MoveResult result = moveService.getMove(moveKey);
        // 同人重复只重放待第二人结果：不完成、无快照、不迁移
        assertThat(result.order().status()).isEqualTo(MoveStatus.AWAITING_SECOND);
        assertThat(result.order().secondConfirmer()).isNull();
        assertThat(result.snapshots()).isEmpty();
        assertThat(moveService.listInventory(src)).hasSize(1);
        assertThat(moveService.listInventory(tgt)).isEmpty();
    }
}

