/**
 * 锁定集合全部证物行并校验前置条件。
 * 证物借出（BORROWED）或待核验（TRANSFER_PENDING）时整单 409；
 * 其余不满足项（不存在、封条异常、库位不符、版本不符）收集为 422 逐项说明。
 */
private Map<String, Evidence> lockAndValidate(List<String> keys, MoveConfirmRequest request,
                                              boolean secondConfirm) {
    List<Evidence> locked = evidenceRepository.findByKeysForUpdate(keys);
    Map<String, Evidence> map = locked.stream()
            .collect(Collectors.toMap(Evidence::evidenceKey, Function.identity()));
    for (String key : keys) {
        Evidence evidence = map.get(key);
        if (evidence != null
                && (evidence.status() == EvidenceStatus.BORROWED
                || evidence.status() == EvidenceStatus.TRANSFER_PENDING)) {
            throw ApiException.conflict(
                    "证物" + (evidence.status() == EvidenceStatus.BORROWED ? "借出未归还" : "待核验")
                            + "，禁止确认迁移: " + key);
        }
    }
    List<MovePreconditionException.ItemViolation> violations = new ArrayList<>();
    for (String key : keys) {
        Evidence evidence = map.get(key);
        if (evidence == null) {
            violations.add(MovePreconditionException.ItemViolation.notFound(key));
            continue;
        }
        if (evidence.status() == EvidenceStatus.SEAL_BROKEN) {
            violations.add(MovePreconditionException.ItemViolation.sealAbnormal(key));
        }
        if (!request.sourceLocation().equals(evidence.locationCode())) {
            violations.add(MovePreconditionException.ItemViolation.locationMismatch(
                    key, String.valueOf(evidence.locationCode()), request.sourceLocation()));
        }
        if (evidence.version() != request.expectedVersion()) {
            violations.add(MovePreconditionException.ItemViolation.versionMismatch(
                    key, evidence.version(), request.expectedVersion()));
        }
    }

