public MoveResult confirm(String actorId, MoveConfirmRequest request) {
    List<String> keys = normalizeKeys(request.evidenceKeys());
    if (request.sourceLocation().equals(request.targetLocation())) {
        throw ApiException.badRequest("源库位与目标库位不能相同");
    }
    LocationMoveOrder existing = moveOrderRepository.findByKeyForUpdate(request.moveKey())
            .orElse(null);
    if (existing != null) {
        return handleExisting(actorId, request, keys, existing);
    }
    return createAwaiting(actorId, request, keys);
}

/**
 * 撤销迁移单：仅首人（第一确认保管人）可在第二人完成前撤销；完成后不可撤销。
 */
@Transactional
public MoveOrderView cancel(String actorId, String moveKey) {
    LocationMoveOrder order = moveOrderRepository.findByKeyForUpdate(moveKey)
            .orElseThrow(() -> ApiException.notFound("迁移单不存在: " + moveKey));
    if (!order.firstConfirmer().equals(actorId)) {
        throw ApiException.conflict("仅第一确认保管人可撤销迁移单: " + actorId);
    }
    if (order.status() == MoveStatus.COMPLETED) {
        throw ApiException.conflict("迁移已完成，不可撤销: " + moveKey);
    }
    if (order.status() == MoveStatus.CANCELLED) {
        // 撤销为终态：同键同参重放撤销结果，不重复改写。
        return toView(order);
    }
    LocalDateTime now = LocalDateTime.now();
    if (!moveOrderRepository.cancel(order.id(), actorId, now)) {
        throw ApiException.conflict("迁移单已被并发处理: " + moveKey);
    }
    return toView(moveOrderRepository.findByKey(moveKey).orElseThrow());
}

